<script setup>
import { ref, watch } from 'vue'
import { useHqaShopStore } from '../../stores/hqaShop'
import { money } from '../../data/hqaCatalog'
import '../../assets/hqa-pages.css'
const shop = useHqaShopStore(), message = ref('')
const form = ref({name: '', email: '', phone: ''})
watch(() => shop.viewer, value => { if (value) form.value = { name: value.name || '', email: value.email || '', phone: value.phone || '' } }, { immediate: true })
function saveProfile() { if (!form.value.name.trim() || !form.value.email.trim()) { message.value = 'Vui lòng nhập họ tên và email.'; return }; shop.setViewer(form.value); message.value = 'Đã cập nhật hồ sơ demo.' }
</script>
<template>
  <main class="hqa-page"><nav class="hqa-breadcrumb"><router-link to="/">Trang chủ</router-link> › Tài khoản</nav>
    <div v-if="!shop.viewer" class="hqa-empty"><div class="hqa-empty-icon">♡</div><h1 class="hqa-page-title">Xin chào nàng!</h1><p class="hqa-subtitle" style="margin:0 auto 20px">Đăng nhập để xem thông tin tài khoản và đơn hàng đã lưu trong trình duyệt.</p><router-link class="hqa-primary" to="/dang-nhap">Đăng nhập</router-link></div>
    <template v-else><div class="hqa-eyebrow">MY ACCOUNT</div><h1 class="hqa-page-title">Tài khoản của tôi</h1><div class="hqa-profile-cards" style="margin-top:22px"><aside class="hqa-panel"><div class="hqa-profile-avatar">{{shop.viewer.name?.[0]?.toUpperCase() || 'H'}}</div><h3 style="margin-bottom:8px">{{shop.viewer.name}}</h3><p class="hqa-dim">{{shop.viewer.email}}</p><div class="hqa-line"></div><p class="hqa-dim">Đơn hàng demo: <strong>{{shop.orders.length}}</strong></p><p class="hqa-dim">Sản phẩm yêu thích: <strong>{{shop.favorites.length}}</strong></p><router-link class="hqa-outline" to="/yeu-thich" style="width:100%">♡ Xem yêu thích</router-link><button class="hqa-link-button" type="button" style="margin-top:20px" @click="shop.logout()">Đăng xuất</button></aside><div><form class="hqa-panel" @submit.prevent="saveProfile"><h3>Thông tin cá nhân</h3><div class="hqa-form-field"><label for="profile-name">Họ và tên</label><input id="profile-name" v-model.trim="form.name" required /></div><div class="hqa-form-field"><label for="profile-email">Email</label><input id="profile-email" v-model.trim="form.email" type="email" required /></div><div class="hqa-form-field"><label for="profile-phone">Số điện thoại</label><input id="profile-phone" v-model.trim="form.phone" type="tel" /></div><button class="hqa-primary" type="submit">Lưu thay đổi</button><p v-if="message" class="hqa-dim" role="status" style="margin:10px 0">{{message}}</p></form><section class="hqa-panel" style="margin-top:20px"><h3>Đơn hàng đã đặt (demo)</h3><div v-if="!shop.orders.length" class="hqa-dim">Chưa có đơn hàng. <router-link to="/san-pham" style="color:#a95d73;text-decoration:underline">Mua sắm ngay</router-link></div><article v-for="order in shop.orders" :key="order.id" class="hqa-order-card"><div class="top"><div><strong>{{order.id}}</strong><div class="hqa-dim">{{new Date(order.createdAt).toLocaleString('vi-VN')}}</div></div><span class="hqa-pill">{{order.status}}</span></div><div class="items">{{order.items.map(x=>`${x.name} (${x.size} × ${x.qty})`).join(' · ')}}</div><div style="margin-top:10px"><strong>{{money(order.subtotal+order.shipping)}}</strong></div></article></section></div></div><p class="hqa-note" style="margin-top:20px">Hồ sơ và lịch sử đơn hàng hiện chỉ được lưu cục bộ trên trình duyệt, chưa liên kết cơ sở dữ liệu hoặc tài khoản được xác thực.</p></template>
  </main>
</template>
